def caesar_cipher(text: str, shift: int) -> str:
    res = []
    for ch in text:
        if 'a' <= ch <= 'z':
            res.append(chr((ord(ch) - ord('a') + shift) % 26 + ord('a')))
        elif 'A' <= ch <= 'Z':
            res.append(chr((ord(ch) - ord('A') + shift) % 26 + ord('A')))
        else:
            res.append(ch)
    return ''.join(res)

def extract_hashtags(text: str) -> list[str]:
    seen = set()
    res = []
    for word in text.split():
        if word.startswith('#') and len(word) > 1:
            cleaned = ''.join(c.lower() for c in word[1:] if c.isalnum())
            if cleaned and cleaned not in seen:
                seen.add(cleaned)
                res.append(cleaned)
    return res

def mask_credit_card(card: str) -> str:
    if len(card) <= 8:
        return card
    return card[:4] + ('*' * (len(card) - 8)) + card[-4:]

def count_letters(s: str) -> dict[str, int]:
    vowels = set('aeiou')
    v_count, c_count = 0, 0
    for ch in s.lower():
        if 'a' <= ch <= 'z':
            if ch in vowels:
                v_count += 1
            else:
                c_count += 1
    return {'vowels': v_count, 'consonants': c_count}

def longest_common_prefix(strs: list[str]) -> str:
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix

def to_snake_case(s: str) -> str:
    res = []
    for i, c in enumerate(s):
        if c.isupper():
            if i != 0 and s[i-1].isalnum() and not s[i-1].isupper():
                res.append('_')
            res.append(c.lower())
        else:
            res.append(c)
    return ''.join(res)

def word_wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []
    lines = []
    cur_line = []
    cur_len = 0
    for w in words:
        if cur_len + len(w) + (1 if cur_line else 0) <= width:
            cur_line.append(w)
            cur_len += len(w) + (1 if len(cur_line) > 1 else 0)
        else:
            if cur_line:
                lines.append(' '.join(cur_line))
            cur_line = [w]
            cur_len = len(w)
    if cur_line:
        lines.append(' '.join(cur_line))
    return lines

def compress_string(s: str) -> str:
    if not s:
        return s
    res = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append(f'{cur}{cnt}')
            cur = ch
            cnt = 1
    res.append(f'{cur}{cnt}')
    compressed = ''.join(res)
    return compressed if len(compressed) < len(s) else s
